function itemDiscount(line,kind){let gross=kind==='service'?Number(line.charge||0):Number(line.qty||0)*Number(line.price||0),value=Number(line.discount||0);return round(line.discountType==='percent'?gross*value/100:value)}
function itemNet(line,kind){let gross=kind==='service'?Number(line.charge||0):Number(line.qty||0)*Number(line.price||0);return round(gross-itemDiscount(line,kind))}
function hasItemDiscount(b){return [...b.serviceLines||[],...b.partLines||[]].some(l=>Number(l.discount||0)!==0)}
const splitBeforeItems=splitDiscounts;
splitDiscounts=function(b){let d=splitBeforeItems(b),serviceLines=(b.serviceLines||[]).reduce((s,l)=>s+itemDiscount(l,'service'),0),partLines=(b.partLines||[]).reduce((s,l)=>s+itemDiscount(l,'part'),0);return {...d,service:round(serviceLines+(b.serviceDiscountType==='percent'?(d.labour-serviceLines)*Number(b.serviceDiscount||0)/100:Number(b.serviceDiscount||0))),part:round(partLines+(b.partsDiscountType==='percent'?(d.parts-partLines)*Number(b.partsDiscount||0)/100:Number(b.partsDiscount||0)))}};
const totalsBeforeItems=billTotals;
billTotals=function(b){if(!hasItemDiscount(b))return totalsBeforeItems(b);let d=splitDiscounts(b),service=Math.max(0,d.labour-d.service),parts=Math.max(0,d.parts-d.part),netParts=(b.partLines||[]).reduce((s,l)=>s+itemNet(l,'part'),0),taxParts=(b.partLines||[]).reduce((s,l)=>s+itemNet(l,'part')*Number(l.gst||0)/100,0),after=service+parts,factor=after?Math.max(0,after-Number(b.discount||0))/after:0,tax=b.invoiceType==='non-gst'?0:round((service*Number(b.tax||0)/100+(netParts?taxParts*parts/netParts:0))*factor);return {labour:d.labour,parts:d.parts,tax,total:round(Math.max(0,after-Number(b.discount||0))+tax)}};
const lineRenderBeforeItems=lineRender;
lineRender=function(){lineRenderBeforeItems();if(!jobDraft||jobDraft.key==='purchases')return;for(let [container,kind,lines]of [['#serviceLines','service',jobDraft.record.serviceLines],['#partLines','part',jobDraft.record.partLines]]){let table=$(container+' table');if(!table)continue;let header=table.tHead?.rows[0]||table.rows[0];let rateIndex=Array.from(header.cells).findIndex(cell=>/Rate|Charge/i.test(cell.textContent));if(rateIndex<0)rateIndex=header.cells.length-2;let th=document.createElement('th');th.textContent='Item Discount';header.insertBefore(th,header.cells[rateIndex+1]);Array.from(table.tBodies[0]?.rows||[]).forEach((row,i)=>{let l=lines[i];if(!l)return;let cell=document.createElement('td');cell.className='itemDiscountCell';cell.innerHTML=`<span class="discountModeToggle" role="group" aria-label="${kind} ${i+1} discount type"><button type="button" data-item-discount="${kind}|${i}|discountType" value="amount" aria-label="Discount in rupees" aria-pressed="${l.discountType!=='percent'}" class="${l.discountType!=='percent'?'active':''}" title="Fixed amount discount">₹</button><button type="button" data-item-discount="${kind}|${i}|discountType" value="percent" aria-label="Percentage discount" aria-pressed="${l.discountType==='percent'}" class="${l.discountType==='percent'?'active':''}" title="Percentage discount">%</button></span><input type="text" inputmode="decimal" autocomplete="off" value="${Number(l.discount||0)}" data-item-discount="${kind}|${i}|discount" aria-label="${kind} ${i+1} discount"><small data-item-net="${kind}|${i}">Net: ${money(itemNet(l,kind))}</small>`;row.insertBefore(cell,row.cells[rateIndex+1])})}};
const updateBeforeItems=updateBillTotals;
updateBillTotals=function(){updateBeforeItems();if(!jobDraft)return;for(let node of $$('[data-item-net]')){let [kind,index]=node.dataset.itemNet.split('|'),line=jobDraft.record[kind==='service'?'serviceLines':'partLines'][index];if(line)node.textContent='Net: '+money(itemNet(line,kind))}for(let [i,l]of jobDraft.record.partLines.entries()){let cell=$('#lineAmount'+i);if(cell)cell.textContent=money(itemNet(l,'part')*(1+Number(jobDraft.record.invoiceType==='non-gst'?0:l.gst||0)/100))}};
document.addEventListener('input',e=>{let data=e.target.dataset.itemDiscount;if(!data||!jobDraft)return;let [kind,index,key]=data.split('|'),line=jobDraft.record[kind==='service'?'serviceLines':'partLines'][index];line[key]=key==='discount'?Number(e.target.value||0):e.target.value;updateBillTotals()},true);
document.addEventListener('change',e=>{let data=e.target.dataset.itemDiscount;if(!data||!jobDraft)return;let [kind,index,key]=data.split('|'),line=jobDraft.record[kind==='service'?'serviceLines':'partLines'][index];line[key]=key==='discount'?Number(e.target.value||0):e.target.value;updateBillTotals()},true);
const saveBeforeItems=saveBill;
saveBill=function(e){if(jobDraft){for(let [kind,lines]of [['service',jobDraft.record.serviceLines],['part',jobDraft.record.partLines]])for(let l of lines||[]){let value=Number(l.discount||0);if(!Number.isFinite(value)||value<0||l.discountType==='percent'&&value>100||itemNet(l,kind)<0){e.preventDefault();return toast('Check each item discount: it cannot exceed 100% or the item amount.')}}let d=splitDiscounts(jobDraft.record);if(d.service>d.labour||d.part>d.parts||Number(jobDraft.record.discount||0)>d.labour+d.parts-d.service-d.part){e.preventDefault();return toast('Combined discounts cannot exceed the bill amount.')}}return saveBeforeItems(e)};
function itemDiscountDescription(l,kind){return Number(l.discount||0)?' [Discount '+(l.discountType==='percent'?Number(l.discount)+'% / INR '+itemDiscount(l,kind).toFixed(2):'INR '+itemDiscount(l,kind).toFixed(2))+']':''}
const receiptRowsBeforeItems=receiptRows;
receiptRows=function(b){return [...(b.partLines||[]).map(l=>({name:(l.name||name('parts',l.part))+itemDiscountDescription(l,'part'),qty:Number(l.qty||0),rate:Number(l.price||0),amount:round(itemNet(l,'part')*(1+Number(b.invoiceType==='non-gst'?0:l.gst||0)/100))})),...(b.serviceLines||[]).map(l=>({name:(l.name||name('services',l.service))+itemDiscountDescription(l,'service'),qty:1,rate:Number(l.charge||0),amount:itemNet(l,'service')}))]};

function invoiceItemDiscountText(line,kind){let amount=itemDiscount(line,kind);return amount?(line.discountType==='percent'?Number(line.discount)+'% ('+money(amount)+')':money(amount)):'—'}
/* Non-GST bills hide tax controls as well as calculating zero tax. */
function syncBillTaxVisibility(){if(!jobDraft||jobDraft.key==='purchases')return;let selector=$('#billForm [name="invoiceType"]'),type=selector?.value||jobDraft.record.invoiceType||'gst';if(selector)jobDraft.record.invoiceType=type;let nonGst=type==='non-gst';let tax=$('#labourTax');if(tax)tax.closest('div').classList.toggle('nonGstTax',nonGst);$('#sumTax')?.closest('div')?.classList.toggle('nonGstTax',nonGst);for(let table of $$('#partLines table')){let header=table.tHead?.rows[0]||table.rows[0];if(!header)continue;let index=Array.from(header.cells).findIndex(c=>/GST/.test(c.textContent));if(index<0)continue;for(let row of table.rows)row.cells[index]?.classList.toggle('nonGstTax',nonGst)}}const updateBeforeTaxVisibility=updateBillTotals;
updateBillTotals=function(){syncBillTaxVisibility();return updateBeforeTaxVisibility()};
const linesBeforeTaxVisibility=lineRender;
lineRender=function(){linesBeforeTaxVisibility();syncBillTaxVisibility()};
const formBeforeTaxVisibility=billForm;
billForm=function(key,id,initial){formBeforeTaxVisibility(key,id,initial);syncBillTaxVisibility();if(jobDraft&&key!=='purchases'){updateBillTotals();if(id&&db.settings.defaultInvoiceType==='non-gst'&&jobDraft.record.invoiceType!=='non-gst'){let form=$('#billForm .formbody');if(form)form.insertAdjacentHTML('afterbegin','<div class="notice">This saved bill uses GST. The Business Settings default applies to new bills. To convert this bill, select Non-GST in Invoice Type and review the revised total before saving.</div>')}}};
const invoiceBeforeHideTax=invoice;
invoice=function(key,id){invoiceBeforeHideTax(key,id);let b=find(key,id);if(!b||invoiceTypeOf(b)!=='non-gst')return;for(let table of $$('#modalBody .invoice table')){let header=table.tHead?.rows[0]||table.rows[0];if(!header)continue;let index=Array.from(header.cells).findIndex(c=>['Tax','GST (%)'].includes(c.textContent.trim()));if(index>=0)for(let row of table.rows)row.cells[index]?.classList.add('nonGstTax')}for(let span of $$('#modalBody .invoicetotal p>span'))if(/Tax \/ Source Adjustment/.test(span.textContent))span.parentNode.classList.add('nonGstTax')};
/* Defaults apply when creating bills/parts; existing saved tax rates remain unchanged. */
const editBeforeDefaultPartGst=editRecord;
editRecord=function(key,id,initial={}){if(key==='parts'&&!id)initial={gst:0,...initial};return editBeforeDefaultPartGst(key,id,initial)};
const settingsBeforeGstHelp=settingsPage;
settingsPage=function(){return settingsBeforeGstHelp()+'<div class="notice">Service / Labour GST is selected per service line in the job card. Spare Parts GST is selected when adding a part. Existing bills keep their saved rates. Non-GST bills apply no GST.</div>'};document.addEventListener('click',e=>{let button=e.target.closest('button[data-item-discount]');if(!button||!jobDraft)return;let [kind,index,key]=button.dataset.itemDiscount.split('|');if(key!=='discountType')return;let line=jobDraft.record[kind==='service'?'serviceLines':'partLines'][Number(index)];if(!line)return;line.discountType=button.value;let group=button.closest('.discountModeToggle');for(let choice of group.querySelectorAll('button')){let active=choice.value===line.discountType;choice.classList.toggle('active',active);choice.setAttribute('aria-pressed',String(active))}updateBillTotals()},true);
render();

